/* OEM trigger/sensor audit — 2026-11-04.
 * Exact-year sources: properties are donor-scoped, not Brick sync tests.
 * No input type, tooth count or ECU fit is guessed when source doesn't establish it.
 */
(()=>{
"use strict";
const all=window.BRICK_ENGINE_PRESETS;
if(!Array.isArray(all))return;
const studies=[{"models":["Ecotec L61 2.2"],"source":"https://charm.li/Saturn/2004/L%20Series%20L4-2.2L%20VIN%20F/Repair%20and%20Diagnosis/Powertrain%20Management/Ignition%20System/Description%20and%20Operation/","scope":"2004 Saturn L-series Ecotec L61 VIN F OEM ignition system","crank":"L61 OEM crank reluctor: 7 slots per revolution. Six are spaced 60° apart; seventh indexing slot is 10° after one main slot (GM 7X), NOT a regular 7-tooth wheel.","ckp":"Variable reluctance / passive magnetic CKP, two-wire AC signal","cam":"No physical cam tooth pickup on this 2004 L61. Factory ICM generates synthetic cam-phase information using compression-sense ignition.","cmp":"Synthesized CAMOUT from ignition control module; no separate OEM cam pickup in 2004 VIN F reference","decoder":"rusEFI GM_7X crank decoder is a geometric candidate. The original ICM's synthetic CAMOUT and coil protocol have not been shown compatible with either Brick; this is a separate integration limit.","ignition":"Factory ignition cassette: two wasted-spark coils; ICM contains the primary drivers, with PCM-controlled timing. Requires validation of ICM input and CAMOUT or different supported ignition strategy.","status":"wheel-sourced"},{"models":["2AR-FE 2.5"],"source":"https://charm.li/Toyota/2009/RAV4%204WD%20L4-2.5L%20%282AR-FE%29/Repair%20and%20Diagnosis/A%20L%20L%20%20Diagnostic%20Trouble%20Codes%20%28%20DTC%20%29/Testing%20and%20Inspection/P%20Code%20Charts/P0335/","scope":"2009 Toyota RAV4 2AR-FE factory CKP service text","crank":"2AR-FE: 34 physical teeth per crank revolution at nominal 10° pitch (36 positions, 2 missing = 36-2).","ckp":"Passive VR / magnetic pickup (iron core, permanent magnet and copper winding)","cam":"Separate intake and exhaust CMP/VVT targets (G2 and EV1 in Toyota service scope); exact cam tooth geometry not in this source.","cmp":"Intake cam MRE magnetic-resistance sensor is documented by the 2010 2AR-FE OEM service text; exhaust sensor type and both cam wheel geometries remain open","decoder":"rusEFI generic 36-2 crank wheel can describe the 2AR-FE sourced crank shape; donor cam targets and full-cycle decoder pairing not yet sourced.","status":"wheel-sourced"},{"models":["2GR-FE 3.5 V6"],"source":"https://charm.li/Toyota/2010/RAV4%202WD%20V6-3.5L%20%282GR-FE%29/Repair%20and%20Diagnosis/A%20L%20L%20%20Diagnostic%20Trouble%20Codes%20%28%20DTC%20%29/Testing%20and%20Inspection/P%20Code%20Charts/P0335/","scope":"2010 Toyota RAV4 2GR-FE OEM P0335 crank sensor description","crank":"2GR-FE: 34 physical teeth per crank rotation (36-2 missing two positions), OEM pickup coil.","ckp":"Passive variable-reluctance magnetic pickup coil; factory source specifies magnet/iron core/wound wire","cam":"Separate intake/exhaust VVT sensor signals VV1+ and VV2+ in OEM oscilloscope references; exact wheel tooth shapes differ by cam and need service detail.","cmp":"VVT cam-position pickups are present, but their Hall/MRE/VR classification is not established by this particular CKP page","decoder":"rusEFI generic 36-2 describes the sourced crank geometry; full cam phase correlation must be checked against exact 2GR donor.","status":"wheel-sourced"},{"models":["S52B32US"],"source":"https://charm.li/BMW/1998/M3%20Convertible%20%28E36%29%20L6-3152cc%203.2L%20DOHC%20%28S52%29/Repair%20and%20Diagnosis/Powertrain%20Management/Computers%20and%20Control%20Systems/Description%20and%20Operation/Engine%20Control%20System%20Inputs/Crankshaft%20Position%20Sensor/","scope":"1998 BMW S52 with Siemens MS41 OEM CKP sensor service","crank":"S52 MS41.x: internal rear-crankshaft 60-2 target (58 physical teeth and a two-tooth gap). Do not copy front-crank mounting from M50/M52 non-US engines.","ckp":"Powered Hall-effect crank sensor, 5 V supply and digital output; OEM MS41.x description","cam":"S52 single VANOS uses an intake cam phase reference; exact OEM cam sensor frequency/shape still to match its Siemens system.","cmp":"OEM S52 cam electrical method unresolved in this direct CKP service source","decoder":"rusEFI generic 60-2 can model the documented S52 crank pattern; factory cam phase sensor may need independent interface work.","status":"wheel-sourced"},{"models":["AAA 2.8 VR6 12V"],"source":"https://the-corrado.net/wiki/vr6_engine_technical_info.html","scope":"VW AAA 2.8 VR6, Bosch Motronic M2.9 VW self-study training reproduced in Corrado Wiki","crank":"AAA 12V: crank-mounted reference wheel with a gap of two teeth, per VW AAA service training. This source does not confirm total tooth count; 60-2 is a candidate, not a source-proven number.","ckp":"Crank position/speed sender G28 (sensor electrical technology not explicitly identified in this specific VW training excerpt)","cam":"One cam-speed Hall reference in distributor, one event per 720° crank cycle.","cmp":"Hall-effect G40 with one electrical reference pulse per 2 crank rotations","decoder":"Generic rusEFI missing-tooth crank + Hall single tooth phase is a candidate if the actual nominal crank wheel count and edge are confirmed; not a proven AAA-specific decoder."},{"models":["2.7T BEL 30V"],"source":"https://charm.li/Audi/2004/A6%20Quattro%20Sedan%20%284B2%29%20V6-2.7L%20Turbo%20%28BEL%29/Repair%20and%20Diagnosis/Powertrain%20Management/Computers%20and%20Control%20Systems/Testing%20and%20Inspection/Component%20Tests%20and%20General%20Diagnostics/Engine%20Speed%20%28RPM%29%20Sensor%20-G28-%2C%20Checking/With%20Generic%20Scan%20Tool/","scope":"2004 Audi A6 2.7T BEL factory G28 service test","crank":"BEL: factory crank speed sensor G28 scans a ring having an enlarged gap reference. The exact total number of teeth is not specified in this BEL service test; a nominal 60-2 hypothesis requires a matching wheel source.","ckp":"Passive inductive / variable-reluctance CKP (OEM resistance 730–1000 ohms between the two signal poles; shield is separate)","cam":"Factory G40 Hall phase sensor used for bank phase; 2.7T cam phasers and wheel reference must be verified for BEL donor year.","cmp":"Hall phase reference G40 on 2.7T; second bank sensor signal/phase still needs donor-specific confirmation","decoder":"A generic 60-2 crank plus Hall phase is a candidate, not an audited BEL factory wheel pairing."},{"models":["Skyactiv-G 2.0","Skyactiv-G 2.5"],"source":"https://charm.li/Mazda/Mazda6%2011%2F2014%20-%2007%2F2016%20%28d9h4-1a-22c_ver13%29/esicont/srvc/html/id0140g2006300.html","scope":"Mazda6 November 2014–July 2016 Skyactiv-G 2.0/2.5 OEM CKP component description","ckp":"Powered magnetic-resistance (MR/MRE) crank sensor element; this is not a passive inductive winding.","cmp":"Cam sensor types and wheel patterns remain unspecified by this CKP overview","decoder":"Do not map the rusEFI Mazda L-series / 36-2-2-2 decoder to Skyactiv-G without actual Skyactiv wheel documentation."},{"models":["M112 3.2 V6"],"source":"https://workshop-manuals.com/mercedesbenz/slk_32_amg_%28170.466%29/v6-3.2l_sc_%28112.960%29/powertrain_management/computers_and_control_systems/sensors_and_switches_computers_and_control_systems/crankshaft_position_sensor/component_information/description_and_operation/crankshaft_position_sensor_location/task/design/function/page_3937/","scope":"2003 Mercedes SLK32 AMG M112.960 OEM CKP sensor service page","crank":"M112.960 crank ring has a two-missing-tooth gap in the OEM reference. Total nominal positions are not established in this page; don't publish 60-2 as verified without a second source.","ckp":"Passive inductive / VR sensor, two-pin coax connection, AC sinusoidal tooth pulses","cam":"Factory Hall phase pickup B6/1 is known on M112 family; exact cam target edges need specific reference.","cmp":"Hall-effect cam reference sensor B6/1 documented for M112 family","decoder":"Generic missing-tooth decoder is possible once nominal tooth count and 720° Hall cam pairing are obtained; currently incomplete."},{"models":["3.7 Cyclone"],"source":"https://lemon-manuals.org.ua/Ford/2011/Pickup%20F150%2C%204D%20Pickup%2C%203.7%20M%2C%204WD/Repair%20and%20Diagnosis%20%28Single%20Page%29/Engine%20Performance/System/Engine%20Controls%20-%20Description%20And%20Operation%20%28Except%20Diesel%20%26%20Hybrid%29/Engine%20Control%20Components/Crankshaft%20Position%20%28CKP%29%20Sensor/","scope":"2011 Ford F-150 3.7L crank sensor section (generic Ford 35+gap reference, not uniquely proven 3.7)","crank":"Ford service says 35 teeth + one missing space (36-1) for SOME V6 and V8 engines; this excerpt does not explicitly tie 36-1 to all Cyclone 3.7 donors.","ckp":"Ford service lists both 2-pin VR and 3-pin Hall pickups across applications; specific 2011 3.7 configuration still needs independent confirmation","decoder":"36-1 generic rusEFI is a candidate pending explicit 3.7L sensor/wheel verification."}];
const touched=new Set();
for(const rule of studies){
 for(const e of all.filter(x=>rule.models.includes(x.model))){
  const r=e.research||(e.research={});
  e.triggerGuide ||= {};
  const g=e.triggerGuide;
  for(const k of ["crank","cam","ckp","cmp","decoder","scope"]){
   if(rule[k])g[k]=rule[k];
  }
  if(rule.crank){r.crankWheel=rule.crank;e.crank=rule.crank}
  if(rule.cam){r.camWheel=rule.cam;e.cam=rule.cam}
  if(rule.ckp||rule.cmp){r.electrical=[rule.ckp?"Crank: "+rule.ckp:"",rule.cmp?"Cam: "+rule.cmp:""].filter(Boolean).join("; ");}
  if(rule.decoder)r.decoderCorrelation=rule.decoder;
  if(rule.ignition)e.integration.ignition=rule.ignition;
  if(rule.status)r.status=rule.status;
  r.checked="2026-11-04";
  const note="Sourced reference: "+rule.scope+". This does not establish a running Brick ECU installation or donor-specific wiring.";
  r.notes=[r.notes,note].filter(Boolean).join(" ");
  e.sources=[...new Set([...(e.sources||[]),rule.source])];
  r.sources=[...new Set([...(r.sources||[]),rule.source])];
  e.references ||= [];
  if(!e.references.some(x=>x.url===rule.source))e.references.push({
   url:rule.source,label:"OEM crank/cam sensor reference",scope:rule.scope+"; only stated details are sourced, and remaining details need separate source."
  });
  e.audit||={};
  e.audit.checked="2026-11-04";
  e.audit.researchStatus=r.status;
  e.audit.sourceCount=e.references.length;
  touched.add(e.id);
 }
}
window.BRICK_TRIGGER_AUDIT_UPDATED=touched.size;
})();